export function getActualLength(str) {
    let length = 0;
    for (let i = 0; i < str.length; i++) {
        const charCode = str.charCodeAt(i);

        // 判断字符是否为全角字符
        if (
            (charCode >= 0xFF00 && charCode <= 0xFFEF) || // 全角字符范围
            (charCode >= 0x4E00 && charCode <= 0x9FA5) || // 中文字符范围
            (charCode >= 0x3000 && charCode <= 0x303F)    // 全角标点符号范围
        ) {
            length += 2; // 全角字符算作 2 个字符
        } else {
            length += 1; // 半角字符算作 1 个字符
        }
    }
    return length;
}