import { TableConfig } from "@/store/dictionary";
import ajax from "@code/utils/ajax";
import { Button, Space, Table, TableColumnProps, Tooltip, Drawer, Radio, Checkbox, Input } from "@arco-design/web-react";
import { IconQuestionCircle } from "@arco-design/web-react/icon";
import React, { HTMLProps, useEffect, useMemo, useState } from "react";
import ProTable from "../ProTable";
import { getActualLength } from "@/utils/str";
import Store from "./store";
import classNames from "classnames";
import { useObserver } from "mobx-react-lite";
import { SorterInfo } from "@arco-design/web-react/es/Table/interface";

interface DictionaryTableProps extends HTMLProps<HTMLDivElement> {
    table: TableConfig
}

const structureColumns: TableColumnProps[] = [
    { title: "数据表字段", dataIndex: "key" },
    { title: "字段类型", dataIndex: "type" },
    { title: "字段长度", dataIndex: "length" },
    { title: "是否可为空", dataIndex: "nullable",
        render: (col) => <Checkbox checked={col} />    
    },
    {
        title: "默认值", dataIndex: "default"
    },
    { title: "字段描述", dataIndex: "desc" },
    { title: "字段备注", dataIndex: "comment", 
        render(col, item, index) {
            if(col) return (
                <Tooltip content={<div className="whitespace-pre-wrap">{col}</div>}>
                    <IconQuestionCircle />
                </Tooltip>
            )
            return null;
        },
    },
]

const DictionaryTable = ({ table, ...divProps }: DictionaryTableProps) => {

    const [store] = useState(() => new Store());


    return useObserver(() => {

        const { 
            type, setType, total, setTotal, current, setCurrent, 
            pageSize, setPageSize, loading, setLoading, data, setData,
            orders, setOrders, querys, setQuerys,
        } = store;


        const columns = useMemo(() => {


            const { primary, uniqueKey, column } = table;
    
            return column.filter((o) => o.key != 'tenant').map((o) => {
    
                const title = `${o.key}：${o.desc? `${o.desc}` : ''}`;
                const item = {
                    // className: "whitespace-nowrap",
                    width: (o.comment? 110 : 90) + (getActualLength(title)) * 7,
                    sorter: true,
                    title: (
                        <Space>
                            <span>{title}</span>
                            {o.comment? (
                                <Tooltip content={<div className="whitespace-pre-wrap">{o.comment}</div>}>
                                    <IconQuestionCircle />
                                </Tooltip>
                            ): null}
                        </Space>
                    ),
                    filterDropdown: ({ filterKeys, setFilterKeys, confirm }) => {
                        return (
                          <div className='arco-table-custom-filter'>
                            <Input.Search
                                autoFocus
                                searchButton
                                placeholder='请输入'
                                value={filterKeys[0] || ''}
                                onChange={(value) => {
                                    setFilterKeys(value ? [value] : []);
                                }}
                                onSearch={() => {
                                    confirm();
                                }}
                            />
                          </div>
                        );
                    },
                    ellipsis: o.length? o.length > 60 : false,
                    dataIndex: o.key
                } as TableColumnProps;
    
                if(o.key == primary || o.key == uniqueKey){
                    item.fixed = 'left';
                }

                if(o.key == 'updatedAt'){
                    item.fixed = 'right';
                }
    
                return item;
            })
        },[table])
    
        useEffect(() => {
            if(type == 'data'){
                setLoading(true)
                ajax.post('/apijson/gets', {
                    [`${table.tableName}[]`]: {
                        "query": 2,
                        count: pageSize,
                        page: current,
                        [`${table.tableName}`]: {
                            ...querys,
                            ...orders,
                        }
                    },
                    "info@": `/${table.tableName}[]/info`,
                }).then((res) => {
                    setData(res[table.tableName])
                    setTotal(res.info.total)
                }).finally(() => {
                    setLoading(false)
                })
            }
        },[type, current, pageSize, orders, querys])
    
        return (
            <div {...divProps} className={classNames("h-full flex flex-col pt-4 box-border", divProps.className)}>
                <div className="flex items-center justify-between pb-2">
                    {table.tableName}({table.desc})
                    <Space>
                        <Radio.Group
                            type='button'
                            options={[
                                { value: "structure", label: "数据结构" },
                                { value: "data", label: "查看数据" },
                            ]}
                            value={type}
                            onChange={(v) => setType(v)}
                        />
                    </Space>
                </div>
                <div className="flex-grow">
                    {type == 'structure'? (
                        <ProTable
                            tableLayoutFixed
                            columns={structureColumns}
                            scroll={{
                                y: true,
                            }}
                            data={table.column.filter((o) => o.key != 'tenant')}
                            pagination={false}
                        />
                    ): (
                        <ProTable
                            columns={columns}
                            data={data}
                            loading={loading}
                            onChange={(pagination, sorter, filters) => {
                                console.log('onChange', pagination, sorter, filters);
                                const { field, direction } = sorter as SorterInfo;
                                if(direction){
                                    setOrders({ '@order': `${field}${direction == 'ascend'? '+' : '-'}` })
                                }else {
                                    setOrders({})
                                }
                                const querys: any = {};
                                for (const key in filters) {
                                    const [value] = filters[key];
                                    querys[`${key}$`] = `%${value}%`;
                                }
                                setQuerys(querys);
                            }}
                            scroll={{
                                x: true,
                                y: true,
                            }}
                            pagination={{
                                current: current,
                                pageSize: pageSize,
                                showTotal: true,
                                sizeCanChange: true,
                                sizeOptions:[10,20,50, 100],
                                total: total,
                                onPageSizeChange(size, current) {
                                    setPageSize(size)
                                    setCurrent(current);
                                },
                            }}
                        />
                    )}
                </div>
            </div>
        )
    })
}


export default DictionaryTable