import { observable, action, makeAutoObservable } from 'mobx';

class Store {
    // 当前查看类型
    type: 'structure' | 'data' = 'structure'; // 'structure' | 'data'
    total = 0;
    current = 1;
    pageSize = 50;
    loading = false;
    data = [];
    orders: Record<string, string> = {};
    querys: Record<string, string> = {};

    constructor() {
        // 自动将属性和方法转换为 observable 和 action
        makeAutoObservable(this);
    }

    // 更新类型
    setType = action((type) => {
        this.type = type;
    });

    // 更新总数
    setTotal = action((total) => {
        this.total = total;
    });

    // 更新当前页
    setCurrent = action((current) => {
        this.current = current;
    });

    // 更新每页大小
    setPageSize = action((pageSize) => {
        this.pageSize = pageSize;
    });

    // 更新加载状态
    setLoading = action((loading) => {
        this.loading = loading;
    });

    // 更新数据
    setData = action((data) => {
        this.data = data;
    });


    // 更新排序信息
    setOrders = action((orders) => {
        this.orders = orders;
    })

    // 查询条件
    setQuerys = action((querys) => {
        this.querys = querys;
    })
}

export default Store;